CREATE TABLE subjects(id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE subject_aliases(subject_id TEXT REFERENCES subjects(id) ON DELETE CASCADE, alias TEXT NOT NULL, PRIMARY KEY(subject_id,alias));
CREATE TABLE subject_images(id INTEGER PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES subjects(id), path TEXT NOT NULL, sha256 TEXT NOT NULL, perceptual_hash TEXT NOT NULL, UNIQUE(subject_id,path));
CREATE TABLE source_configs(name TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE collection_runs(id TEXT PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES subjects(id), source TEXT NOT NULL, query TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_run ON collection_runs(subject_id,source,query) WHERE status IN ('PENDING','RUNNING');
CREATE TABLE search_tasks(id TEXT PRIMARY KEY REFERENCES collection_runs(id) ON DELETE CASCADE, checkpoint INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL);
CREATE TABLE mentions(id INTEGER PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES subjects(id), source TEXT NOT NULL, canonical_url TEXT NOT NULL, content_hash TEXT NOT NULL, collected_at TEXT NOT NULL, data TEXT NOT NULL, analysis_status TEXT NOT NULL, UNIQUE(subject_id,source,canonical_url), UNIQUE(subject_id,source,content_hash));
CREATE INDEX mentions_subject ON mentions(subject_id);
CREATE INDEX mentions_source ON mentions(source);
CREATE INDEX mentions_time ON mentions(collected_at);
CREATE INDEX mentions_hash ON mentions(content_hash);
CREATE TABLE mention_media(id INTEGER PRIMARY KEY, mention_id INTEGER NOT NULL REFERENCES mentions(id) ON DELETE CASCADE, url TEXT NOT NULL, sha256 TEXT, perceptual_hash TEXT, distance INTEGER, matches_reference INTEGER NOT NULL DEFAULT 0);
CREATE INDEX media_hash ON mention_media(sha256,perceptual_hash);
CREATE TABLE analysis_results(mention_id INTEGER PRIMARY KEY REFERENCES mentions(id) ON DELETE CASCADE, risk_score INTEGER NOT NULL, sentiment TEXT NOT NULL, category TEXT NOT NULL, requires_review INTEGER NOT NULL, data TEXT NOT NULL);
CREATE INDEX analysis_risk ON analysis_results(risk_score);
CREATE TABLE cases(id INTEGER PRIMARY KEY, mention_id INTEGER NOT NULL UNIQUE REFERENCES mentions(id), status TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL);
CREATE TABLE case_evidence(case_id INTEGER NOT NULL REFERENCES cases(id), mention_id INTEGER NOT NULL REFERENCES mentions(id), screenshot_path TEXT NOT NULL, PRIMARY KEY(case_id,mention_id));
CREATE TABLE approvals(id INTEGER PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES cases(id), decision TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE agent_steps(id INTEGER PRIMARY KEY, run_id TEXT NOT NULL REFERENCES collection_runs(id), step_number INTEGER NOT NULL, observed_url TEXT NOT NULL, proposed_action TEXT NOT NULL, action_arguments TEXT NOT NULL, guardrail_result TEXT NOT NULL, execution_result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, entity TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE system_events(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
